import React from 'react';
import ReactDOM from 'react-dom';
import { Transfer } from '@alifd/next';

const dataSource = [];
for (let i = 0; i < 10; i++) {
  dataSource.push({
    label: `Item ${i}`,
    value: `${i}`,
  });
}

class Demo extends React.Component {
  render() {
    return (
      <Transfer
        dataSource={dataSource}
        defaultValue={['2', '5']}
        showSearch
        // This single searchProps is applied to BOTH panels
        searchProps={{
          hasClear: true,
          placeholder: 'Search only on left (but appears on both)',
          style: { width: 200 },
        }}
        titles={['Left Panel', 'Right Panel']}
      />
    );
  }
}

ReactDOM.render(<Demo />, document.getElementById('mountNode'));
